      "ejemplo": "Mientras lee textos literarios como las fábulas (por ejemplo 'La zorra y las uvas' de Jean de La Fontaine): Hace pausas y cambia ritmos, tonos y velocidades en la lectura. Dialoga sobre lo que entiende de ellas. Expresa cuáles personajes de las fábulas le gustan más y por qué. Opina sobre las acciones, actitudes y decisiones de los personajes de las fábulas.",
      "factor": "Literatura",
