      "ejemplo": "Para comprender textos orales: Participa en conversaciones que recrean situaciones cotidianas en las que identifica las intenciones de su interlocutor para responder de manera adecuada. Representa situaciones en las que simula pedir un favor, solicitar una explicación para hacer una tarea o contar lo realizado el fin de semana anterior. Escucha al otro con actitud de respeto y evalúa la claridad de las ideas, la pronunciación y la gestualidad.",
      "factor": "Comprensión e interpretación textual",
