      "ejemplo": "Para reconocer el propósito de los textos que escribe: Cruza la columna A con la B para relacionar los tipos de texto (Invitación, Nota, Receta, Carta) con las situaciones presentadas (Invitar a la fiesta, Agradecer a tu profesor, Indicar cómo preparar galletas, Informar que el almuerzo está en la nevera). Elige uno de los tipos de textos y lo ejemplifica.",
