      "ejemplo": "Conoce algunas manifestaciones artísticas y culturales colombianas (Carnavales y fiestas más representativos de Colombia: Carnaval de Barranquilla, Festival de la Leyenda Vallenata, Feria de las Flores, Carnaval de Negros y Blancos, Reinado Nacional del Bambuco), y analiza los textos, sonidos e imágenes que se producen en ellas.",
