      "ejemplo": "Analiza el papel del emisor de una comunicación y la información que este emite: ¿Quién es la persona que está hablando? ¿Qué es un biólogo? ¿Cuáles son las características de los gorilas? ¿Para qué nos sirve ver este documental?",
