      "ejemplo": "A partir de una situación específica, como la necesidad que tiene un guía turístico de producir textos: Determina las características de los turistas que constituyen el público al que se va a dirigir. Selecciona la información que necesitan los turistas (ej. folleto sobre el Amazonas). Diseña la forma en que presentará la información.",
      "factor": "Producción textual (escrita)",
