      "ejemplo": "Selecciona un poema y un cuento que aborden un tema semejante y luego de su lectura y análisis, determina: Las diferencias y similitudes en la manera que cada texto presenta la temática, Aspectos representativos de los dos textos, Recursos estilísticos usados para la presentación de la temática, Otros textos con que pueden relacionarse. Crea una cartelera sobre los dos textos leídos y la expone junto a las de sus compañeros en una galería.",
      "factor": "Literatura",
