      "ejemplo": "Al empezar un proceso de escritura enmarcado en una situación comunicativa específica, se pregunta: ¿Qué quiero escribir? ¿Cómo quiero ordenar mi escrito? ¿Es útil acompañar el texto de ilustraciones? ¿Para qué quiero escribir? ¿Para quién voy a escribir?",
