      "enunciado": "Reconoce información específica en textos cortos orales y escritos sobre temas de interés general. Para esto, utiliza diferentes estrategias de lectura: Pre-visualización (imágenes, títulos, subtítulos, etc), Predicción: Subrayado, palabras claves o parecidas al español; identificación del sentido general del texto (skimming). Por ejemplo,.",
      "evidencias": [
        "English around the World: People use words to express their ideas, intentions, emotions and information... The English language has More than 500.000 words... Some words that English speakers use are taken from different languages: Avocato, Barbecue, Totem, Jungle, Yoga, Kangaroo, Ketchup, Color... English is Everywhere. | Reading strategy: Predicting Key words (How many times do these words occur: English, language(s), word?) - Reading strategy: Predicting Cognates (Find words that are similar to Spanish words)."
      ],
      "ejemplo": "English around the World: People use words to express their ideas, intentions, emotions and information... The English language has More than 500.000 words... Some words that English speakers use are taken from different languages: Avocato, Barbecue, Totem, Jungle, Yoga, Kangaroo, Ketchup, Color... English is Everywhere. | Reading strategy: Predicting Key words (How many times do these words occur: English, language(s), word?) - Reading strategy: Predicting Cognates (Find words that are similar to Spanish words).",
