      "enunciado": "Hace exposiciones breves sobre un tema académico relacionado con su entorno escolar o su comunidad y tiene en cuenta: hechos relevantes, detalles concretos y vocabulario específico. Para esto, se ha preparado previamente y se ha asesorado con sus compañeros y profesor.",
      "evidencias": [
        "Good morning! My purpose today is to talk about language. Language is the ability to acquire and use the system of communication. There are about 5.000 to 7.000 languages in the world. When we communicate, we can use words, symbols, gestures, movements, or images. It means that language can be verbal (words: spoken or written) and symbolic (images, gestures, movements, symbols). In conclusion, we use language to interact with other people, to express our ideas, feelings and emotions."
      ],
      "ejemplo": "Good morning! My purpose today is to talk about language. Language is the ability to acquire and use the system of communication. There are about 5.000 to 7.000 languages in the world. When we communicate, we can use words, symbols, gestures, movements, or images. It means that language can be verbal (words: spoken or written) and symbolic (images, gestures, movements, symbols). In conclusion, we use language to interact with other people, to express our ideas, feelings and emotions.",
