      "title": "Narración autobiográfica en pasado con conectores de secuencia.",
      "enunciado": "Narra brevemente hechos actuales, situaciones cotidianas o sus experiencias propias, en forma oral o escrita. Para esto, tiene en cuenta la secuencia de las acciones, la claridad de las ideas y se asesora con sus compañeros y su profesor.",
