      "ejemplo": "My first trip... The first time I left my small town was when I went to the capital. We had a school visit to a local newspaper printing plant to understand the process of producing and printing the newspaper. When we finished the activity, we went to a mall. It was exciting for me because I have never been to a mall before. There were some things which surprised me because I have never seen them, such as: the electronic stairs and the elevator. I was afraid first but once I tried them, I really enjoyed it!",
