      "enunciado": "Reconoce relaciones de causa y efecto en lecturas cortas sobre temas académicos. Para esto, tiene en cuenta el vocabulario, los conectores y sus conocimientos previos. Por ejemplo, después de leer un texto corto, puede identificar las causas y efectos y representarlos a través de un gráfico.",
      "evidencias": [
        "ENDANGERED SPECIES: Endangered species are those plants and animals that are in danger of extinction... Extinction is a very normal process in the evolution of animals and plants. The causes can be related to survival, climate, and human intervention... [Gráfico causal: EXTINCTION <- Survival, Climate, Human intervention (Chemical pollution, Destruction of habitats, Exploitation of plants and animals)]."
      ],
      "ejemplo": "ENDANGERED SPECIES: Endangered species are those plants and animals that are in danger of extinction... Extinction is a very normal process in the evolution of animals and plants. The causes can be related to survival, climate, and human intervention... [Gráfico causal: EXTINCTION <- Survival, Climate, Human intervention (Chemical pollution, Destruction of habitats, Exploitation of plants and animals)].",
