      "enunciado": "Redacta textos de mediana longitud en los cuales realiza recomendaciones o sugerencias sobre situaciones de interés personal, escolar o social. Para ello, tiene en cuenta las relaciones de contraste, comparación, adición, entre otras. Por ejemplo, después de ver un video sobre el manejo seguro de las redes sociales, escribe un texto sobre recomendaciones para publicarlo en el periódico escolar.",
