      "enunciado": "Redacta textos narrativos, descriptivos y expositivos relacionados con temas de su interés o que le resultan familiares. Para esto, sigue un proceso de planeación, escritura, revisión y edición. Se apoya en su profesor(a) y/o compañeros(as) de clase. Por ejemplo, sigue esta estructura para escribir un texto.",
