      "dba_num": 4,
      "title": "Redacción de correspondencia formal de justificación médica.",
      "enunciado": "Produce mensajes escritos, tales como cartas y correos electrónicos, claros y bien estructurados teniendo en cuenta el contexto en el que tienen lugar. Para esto, utiliza el vocabulario y las estructuras de texto requeridas. Por ejemplo, al escribir un correo electrónico saluda, escribe su mensaje y se despide.",
