      "enunciado": "Intercambia opiniones sobre situaciones de interés personal, escolar o social. Para esto, presenta sus opiniones de manera natural y coherente y hace uso de expresiones conocidas. Por ejemplo, participa en una mesa redonda dando opiniones sobre el tema en discusión.",
