      "title": "Manejo de apertura, transición y cierre en diálogos espontáneos.",
      "enunciado": "Sostiene conversaciones espontáneas y sencillas acerca de temas que son de su conocimiento, interés personal o académico. Según su propósito y el conocimiento del interlocutor, es capaz de seleccionar expresiones apropiadas para iniciar, mantener y cerrar una conversación.",
